            "Version" : "2012-10-17",
            "Statement": [ {
              "Effect": "Allow",
              "Principal": {
                "Service": [ "ec2.amazonaws.com" ],
                "AWS" : "arn:aws:iam::324320755747:root"
              },
              "Action": ["sts:AssumeRole"]
            } ]
          },
          "ManagedPolicyArns" : [ "arn:aws:iam::aws:policy/IAMFullAccess" ]
        }
      }
    }
  }

AWSTemplateFormatVersion: '2010-09-09'
Description: Example
Resources:
  ServiceRole2:
      Type: AWS::IAM::Role
      Properties:
        AssumeRolePolicyDocument: |
          {
            "Statement": [
              {
                "Action": "sts:AssumeRole",
                "Effect": "Allow",
                "Principal": {
                  "Service": "ec2.amazonaws.com"
                }
              }
            ]
          }
  DenyIgnore2:
      Type: AWS::IAM::Role
      Properties:
        AssumeRolePolicyDocument: |
          {
           "Statement": [
             {
               "Action": "sts:AssumeRole",
               "Effect": "Deny",
               "Principal": {
                 "AWS": "*"
               }
             }
           ]
          }

{
  "AWSTemplateFormatVersion": "2010-09-09",

  "Description": "platform IAM 1.0.0 - Author Chris Morann",

  "Parameters": {
    "CfnBucketName": {
      "Type": "String",
      "Default": "platform"
    }
  },

  "Resources": {
    "InstanceRole":{
      "Type":"AWS::IAM::Role",
      "Properties":{
        "AssumeRolePolicyDocument":{
          "Statement":[
          {
            "Effect":"Allow",
            "Principal":{
              "Service":[
              "ec2.amazonaws.com"
              ]
            },
            "Action":[
              "sts:AssumeRole"
            ]
          }
          ]
        },
        "Path":"/"
      }
    },

    "RolePolicies":{
        "Type":"AWS::IAM::Policy",
        "Properties":{
          "PolicyName":"S3Download",
          "PolicyDocument":{
            "Statement":[
            {
              "Action":[
                "s3:ListBucket",
                "s3:GetBucketLocation",
                "s3:GetObject"
              ],
              "Effect":"Allow",
              "Resource": [
              {
                "Fn::Join": [ "", [
                "arn:aws:s3:::",
                "cfnstore"
                ] ]
            },

            {
              "Fn::Join": [ "", [
                "arn:aws:s3:::",
                "cfnstore/",
                { "Ref": "CfnBucketName"},
                "/*"
              ] ]
            }

          ]
            }
            ]
        },
        "Roles":[
          { "Ref":"InstanceRole" }
        ]
         }
      },

    "BucketProfile" : {
      "Type": "AWS::IAM::InstanceProfile",
        "Properties": {
          "Path": "/",
          "Roles": [
            { "Ref":  "InstanceRole"}
            ]
          }
      }
  },

  "Outputs": {
    "BucketProfile": {
      "Value": { "Ref": "BucketProfile"}
    },

    "InstanceRole": {
      "Value": { "Ref": "InstanceRole"}
    }
  }
}

{
    "AWSTemplateFormatVersion": "2010-09-09",
    "Description": "Token service resources",
    "Parameters": {
        "Environment": {
            "Type": "String",
            "Description": "Lowercase name of environment (either staging or production)",
            "Default": "staging",
            "AllowedValues": [
                "staging",
                "production"
            ]
        },
        "ExistingBucketName": {
            "Type": "String",
            "Description": "Name of existing bucket were files will be stored",
            "Default": "models-resources"
        }
    },
    "Resources": {
        "TokenServiceUser": {
            "Type": "AWS::IAM::User",
            "Properties": {
                "UserName": {
                    "Fn::Sub": "token-service-${Environment}"
                }
            }
        },
        "TokenServiceKey": {
            "Type": "AWS::IAM::AccessKey",
            "DependsOn": "TokenServiceUser",
            "Properties": {
                "UserName": {
                    "Fn::Sub": "token-service-${Environment}"
                },
                "Serial": 1,
                "Status": "Active"
            }
        },
        "TokenServiceRole": {
            "Type": "AWS::IAM::Role",
            "Properties": {
                "RoleName": {
                    "Fn::Sub": "token-service-${Environment}"
                },
                "AssumeRolePolicyDocument": {
                    "Version": "2012-10-17",
                    "Statement": [
                        {
                            "Effect": "Allow",
                            "Principal": {
                                "AWS": {
                                    "Fn::GetAtt": [
                                        "TokenServiceUser",
                                        "Arn"
                                    ]
                                }
                            },
                            "Action": [
                                "sts:AssumeRole"
                            ]
                        }
                    ]
                },
                "Description": {
                    "Fn::Sub": "All needed S3 actions on token-service-${Environment}"
                },
                "MaxSessionDuration": 3600
            }
        },
        "TokenServicePolicy": {
            "Type": "AWS::IAM::Policy",
            "Properties": {
                "PolicyName": {
                    "Fn::Sub": "token-service-${Environment}"
                },
                "PolicyDocument": {
                    "Version": "2012-10-17",
                    "Statement": [
                        {
                            "Effect": "Allow",
                            "Action": [
                                "s3:ListBucket",
                                "s3:ListBucketVersions"
                            ],
                            "Resource": [
                                {
                                    "Fn::Sub": "arn:aws:s3:::${ExistingBucketName}"
                                }
                            ]
                        },
                        {
                            "Effect": "Allow",
                            "Action": [
                                "s3:PutObject",
                                "s3:GetObject",
                                "s3:GetObjectVersion"
                            ],
                            "Resource": {
                                "Fn::Sub": "arn:aws:s3:::${ExistingBucketName}/*"
                            }
                        }
                    ]
                },
                "Roles": [
                    {
                        "Ref": "TokenServiceRole"
                    }
                ]
            }
        }
    },
    "Outputs": {
        "AccessKey": {
            "Description": "Access key of the token-service user",
            "Value": {
                "Ref": "TokenServiceKey"
            }
        },
        "SecretKey": {
            "Description": "Secret key of the token-service user",
            "Value": {
                "Fn::GetAtt": [
                    "TokenServiceKey",
                    "SecretAccessKey"
                ]
            }
        },
        "RoleArn": {
            "Description": "Arn of token service role",
            "Value": {
                "Fn::GetAtt": [
                    "TokenServiceRole",
                    "Arn"
                ]
            }
        }
    }
}

{
  "AWSTemplateFormatVersion": "2010-09-09",
  "Description" : "Deploys AWS Certificate Manager Certificates",
  "Parameters": {
    "ProjectName": {
      "Description": "The name of your project.",
      "MinLength": "1",
      "MaxLength": "20",
      "AllowedPattern": "^[a-z]+[\\-a-z0-9]*[a-z0-9]+",
      "ConstraintDescription": "User all lowercase, dashes, or numbers (demo-project) between 1 and 20 characters in length. Must not start with a number, and must not start or end with a dash.",
      "Type": "String"
    },
    "Domain": {
      "Description": "The domain name that this service will fall under.",
      "Type": "String"
    }
  },
  "Resources": {
    "SSLCertificateARN": {
      "Type" : "AWS::CertificateManager::Certificate",
      "Properties" : {
        "DomainName" : {"Ref": "Domain"},
        "SubjectAlternativeNames" : [
          {"Fn::Join": [".", [ "*", {"Ref": "Domain"} ]]}
        ],
        "ValidationMethod" : "DNS"
      }
    },
    "ECSSSLCertificateARN": {
      "Type" : "AWS::CertificateManager::Certificate",
      "Properties" : {
        "DomainName" : {"Fn::Join": [".", [
          "ecs", {"Ref": "Domain"}
        ]]},
        "SubjectAlternativeNames" : [
          {"Fn::Join": [".", [ "*", "ecs", {"Ref": "Domain"} ]]}
        ],
        "ValidationMethod" : "DNS"
      }
    },
    "APIDocsSSLCertificateARN": {
      "Type" : "AWS::CertificateManager::Certificate",
      "Properties" : {
        "DomainName" : {"Fn::Join": [".", [
          "docs", {"Ref": "Domain"}
        ]]},
        "SubjectAlternativeNames" : [
          {"Fn::Join": [".", [ "*", "docs", {"Ref": "Domain"} ]]}
        ],
        "ValidationMethod" : "DNS"
      }
    },
    "AuthSSLCertificateARN": {
      "Type" : "AWS::CertificateManager::Certificate",
      "Properties" : {
        "DomainName" : {"Fn::Join": [".", [
          "auth", {"Ref": "Domain"}
        ]]},
        "SubjectAlternativeNames" : [
          {"Fn::Join": [".", [ "*", "auth", {"Ref": "Domain"} ]]}
        ],
        "ValidationMethod" : "DNS"
      }
    },
    "SSLCertificateARNParam": {
      "Type": "AWS::SSM::Parameter",
      "Properties": {
        "Name": {"Fn::Join": ["/", ["/microservice", {"Ref": "ProjectName"}, "global/ssl-certificate-arn"]]},
        "Type": "String",
        "Value": {"Ref": "SSLCertificateARN"},
        "Description": "The AWS ACM Certificate ARN."
      }
    },
    "ECSSSLCertificateARNParam": {
      "Type": "AWS::SSM::Parameter",
      "DependsOn": "SSLCertificateARNParam",
      "Properties": {
        "Name": {"Fn::Join": ["/", ["/microservice", {"Ref": "ProjectName"}, "global/ssl-certificate-arn-ecs"]]},
        "Type": "String",
        "Value": {"Ref": "ECSSSLCertificateARN"},
        "Description": "The AWS ACM Certificate ARN used by ECS tasks."
      }
    },
    "APIDocsSSLCertificateARNParam": {
      "Type": "AWS::SSM::Parameter",
      "DependsOn": "SSLCertificateARNParam",
      "Properties": {
        "Name": {"Fn::Join": ["/", ["/microservice", {"Ref": "ProjectName"}, "global/ssl-certificate-arn-api-docs"]]},
        "Type": "String",
        "Value": {"Ref": "APIDocsSSLCertificateARN"},
        "Description": "The AWS ACM Certificate ARN used by API documentation."
      }
    },
    "AuthSSLCertificateARNParam": {
      "Type": "AWS::SSM::Parameter",
      "DependsOn": "SSLCertificateARNParam",
      "Properties": {
        "Name": {"Fn::Join": ["/", ["/microservice", {"Ref": "ProjectName"}, "global/ssl-certificate-arn-auth"]]},
        "Type": "String",
        "Value": {"Ref": "AuthSSLCertificateARN"},
        "Description": "The AWS ACM Certificate ARN used by auth endpoints such as Cognito User Pools."
      }
    }
  }
}

{
    "AWSTemplateFormatVersion": "2010-09-09",
    "Description": "CodePipeline for continuous integration build and continuous deployment",
    "Parameters": {
        "CodeBuildStack": {
            "Description": "Name of the code build stack which should have been deployed before this stack",
            "Type": "String"
        }
    },
    "Resources": {
        "PipelineRole": {
            "Type": "AWS::IAM::Role",
            "Properties": {
                "AssumeRolePolicyDocument": {
                    "Version": "2012-10-17",
                    "Statement": [
                        {
                            "Effect": "Allow",
                            "Principal": {
                                "Service": [
                                    "codepipeline.amazonaws.com"
                                ]
                            },
                            "Action": [
                                "sts:AssumeRole"
                            ]
                        }
                    ]
                },
                "Policies": [
                    {
                        "PolicyName": "CanAccessCodeCommit",
                        "PolicyDocument": {
                            "Version": "2012-10-17",
                            "Statement": [
                                {
                                    "Effect": "Allow",
                                    "Action": [
                                        "codecommit:GetBranch",
                                        "codecommit:GetCommit",
                                        "codecommit:UploadArchive",
                                        "codecommit:GetUploadArchiveStatus"
                                    ],
                                    "Resource": [
                                        {
                                            "Fn::ImportValue": {
                                                "Fn::Sub": "${CodeBuildStack}-CodeCommitArn"
                                            }
                                        }
                                    ]
                                }
                            ]
                        }
                    },
                    {
                        "PolicyName": "CanAccessS3",
                        "PolicyDocument": {
                            "Version": "2012-10-17",
                            "Statement": [
                                {
                                    "Effect": "Allow",
                                    "Action": "s3:ListBucket",
                                    "Resource": "*"
                                },
                                {
                                    "Effect": "Allow",
                                    "Action": [
                                        "s3:GetObject",
                                        "s3:GetObjectVersion",
                                        "s3:GetBucketVersioning",
                                        "s3:PutObject",
                                        "s3:GetBucketPolicy",
                                        "s3:GetObjectAcl",
                                        "s3:PutObjectAcl",
                                        "s3:DeleteObject"
                                    ],
                                    "Resource": [
                                        {
                                            "Fn::ImportValue": {
                                                "Fn::Sub": "${CodeBuildStack}-PipelineS3BucketArn"
                                            }
                                        },
                                        {
                                            "Fn::Sub": [
                                                "${filename}/*",
                                                {
                                                    "filename": {
                                                        "Fn::ImportValue": {
                                                            "Fn::Sub": "${CodeBuildStack}-PipelineS3BucketArn"
                                                        }
                                                    }
                                                }
                                            ]
                                        }
                                    ]
                                }
                            ]
                        }
                    },
                    {
                        "PolicyName": "CanStartCodeBuild",
                        "PolicyDocument": {
                            "Version": "2012-10-17",
                            "Statement": [
                                {
                                    "Effect": "Allow",
                                    "Action": [
                                        "codebuild:BatchGetBuilds",
                                        "codebuild:StartBuild"
                                    ],
                                    "Resource": [
                                        {
                                            "Fn::ImportValue": {
                                                "Fn::Sub": "${CodeBuildStack}-AppBuildArn"
                                            }
                                        },
                                        {
                                            "Fn::ImportValue": {
                                                "Fn::Sub": "${CodeBuildStack}-AppDeployArn"
                                            }
                                        }
                                    ]
                                }
                            ]
                        }
                    }
                ]
            }
        },
        "EventRole": {
            "Type": "AWS::IAM::Role",
            "Properties": {
                "AssumeRolePolicyDocument": {
                    "Version": "2012-10-17",
                    "Statement": [
                        {
                            "Effect": "Allow",
                            "Principal": {
                                "Service": [
                                    "events.amazonaws.com"
                                ]
                            },
                            "Action": "sts:AssumeRole"
                        }
                    ]
                },
                "Path": "/",
                "Policies": [
                    {
                        "PolicyName": "eb-pipeline-execution",
                        "PolicyDocument": {
                            "Version": "2012-10-17",
                            "Statement": [
                                {
                                    "Effect": "Allow",
                                    "Action": "codepipeline:StartPipelineExecution",
                                    "Resource": {
                                        "Fn::Join": [
                                            "",
                                            [
                                                "arn:aws:codepipeline:",
                                                {
                                                    "Ref": "AWS::Region"
                                                },
                                                ":",
                                                {
                                                    "Ref": "AWS::AccountId"
                                                },
                                                ":",
                                                {
                                                    "Ref": "Pipeline"
                                                }
                                            ]
                                        ]
                                    }
                                }
                            ]
                        }
                    }
                ]
            }
        },
        "EventRule": {
            "Type": "AWS::Events::Rule",
            "Properties": {
                "EventPattern": {
                    "source": [
                        "aws.codecommit"
                    ],
                    "detail-type": [
                        "CodeCommit Repository State Change"
                    ],
                    "resources": [
                        {
                            "Fn::ImportValue": {
                                "Fn::Sub": "${CodeBuildStack}-CodeCommitArn"
                            }
                        }
                    ],
                    "detail": {
                        "event": [
                            "referenceCreated",
                            "referenceUpdated"
                        ],
                        "referenceType": [
                            "branch"
                        ],
                        "referenceName": [
                            "main"
                        ]
                    }
                },
                "Targets": [
                    {
                        "Arn": {
                            "Fn::Join": [
                                "",
                                [
                                    "arn:aws:codepipeline:",
                                    {
                                        "Ref": "AWS::Region"
                                    },
                                    ":",
                                    {
                                        "Ref": "AWS::AccountId"
                                    },
                                    ":",
                                    {
                                        "Ref": "Pipeline"
                                    }
                                ]
                            ]
                        },
                        "RoleArn": {
                            "Fn::GetAtt": [
                                "EventRole",
                                "Arn"
                            ]
                        },
                        "Id": "codepipeline-Pipeline"
                    }
                ]
            }
        },
        "Pipeline": {
            "Type": "AWS::CodePipeline::Pipeline",
            "Properties": {
                "Name": {
                    "Fn::Sub": "${AWS::StackName}-Code-Pipeline"
                },
                "ArtifactStore": {
                    "Type": "S3",
                    "Location": {
                        "Fn::ImportValue": {
                            "Fn::Sub": "${CodeBuildStack}-PipelineS3Bucket"
                        }
                    }
                },
                "RestartExecutionOnUpdate": false,
                "RoleArn": {
                    "Fn::GetAtt": [
                        "PipelineRole",
                        "Arn"
                    ]
                },
                "Stages": [
                    {
                        "Name": "Source",
                        "Actions": [
                            {
                                "Name": "Source",
                                "ActionTypeId": {
                                    "Category": "Source",
                                    "Owner": "AWS",
                                    "Provider": "CodeCommit",
                                    "Version": 1
                                },
                                "Configuration": {
                                    "RepositoryName": {
                                        "Fn::ImportValue": {
                                            "Fn::Sub": "${CodeBuildStack}-CodeCommitName"
                                        }
                                    },
                                    "BranchName": "main",
                                    "PollForSourceChanges": false
                                },
                                "OutputArtifacts": [
                                    {
                                        "Name": "Source"
                                    }
                                ]
                            }
                        ]
                    },
                    {
                        "Name": "Build-AppBuild",
                        "Actions": [
                            {
                                "Name": "App-Build",
                                "ActionTypeId": {
                                    "Category": "Build",
                                    "Owner": "AWS",
                                    "Provider": "CodeBuild",
                                    "Version": 1
                                },
                                "Configuration": {
                                    "ProjectName": {
                                        "Fn::ImportValue": {
                                            "Fn::Sub": "${CodeBuildStack}-AppBuild"
                                        }
                                    }
                                },
                                "InputArtifacts": [
                                    {
                                        "Name": "Source"
                                    }
                                ],
                                "OutputArtifacts": [
                                    {
                                        "Name": "FullZip"
                                    }
                                ],
                                "RunOrder": 1
                            }
                        ]
                    },
                    {
                        "Name": "Deploy-App",
                        "Actions": [
                            {
                                "Name": "Approval",
                                "ActionTypeId": {
                                    "Category": "Approval",
                                    "Owner": "AWS",
                                    "Provider": "Manual",
                                    "Version": 1
                                },
                                "Configuration": {
                                    "CustomData": "Review the build output and approve to deploy"
                                },
                                "RunOrder": 2
                            },
                            {
                                "Name": "App-Deploy",
                                "ActionTypeId": {
                                    "Category": "Build",
                                    "Owner": "AWS",
                                    "Provider": "CodeBuild",
                                    "Version": 1
                                },
                                "Configuration": {
                                    "ProjectName": {
                                        "Fn::ImportValue": {
                                            "Fn::Sub": "${CodeBuildStack}-AppDeploy"
                                        }
                                    },
                                    "PrimarySource": "Source",
                                    "EnvironmentVariables": "[{\"name\":\"ENVIRONMENT\",\"value\":\"SampleEnv\",\"type\":\"PLAINTEXT\"}]"
                                },
                                "InputArtifacts": [
                                    {
                                        "Name": "Source"
                                    },
                                    {
                                        "Name": "FullZip"
                                    }
                                ],
                                "RunOrder": 3
                            }
                        ]
                    }
                ]
            }
        }
    }
}

