                        },
                        {
                            "InputStrength": "HIGH",
                            "OutputStrength": "HIGH",
                            "Type": "VIOLENCE"
                        },
                        {
                            "InputStrength": "HIGH",
                            "OutputStrength": "HIGH",
                            "Type": "HATE"
                        },
                        {
                            "InputStrength": "HIGH",
                            "OutputStrength": "HIGH",
                            "Type": "INSULTS"
                        },
                        {
                            "InputStrength": "HIGH",
                            "OutputStrength": "HIGH",
                            "Type": "MISCONDUCT"
                        },
                        {
                            "InputStrength": "NONE",
                            "OutputStrength": "NONE",
                            "Type": "PROMPT_ATTACK"
                        }
                    ]
                },
                "SensitiveInformationPolicyConfig": {
                    "PiiEntitiesConfig": [
                        {
                            "Action": "BLOCK",
                            "Type": "EMAIL"
                        },
                        {
                            "Action": "ANONYMIZE",
                            "Type": "IP_ADDRESS"
                        }
                    ]
                },
                "TopicPolicyConfig": {
                    "TopicsConfig": [
                        {
                            "Definition": "Investment advice is inquiries, guidance, or recommendations about the management or allocation of funds or assets with the goal of generating returns or achieving specific financial objectives.",
                            "Examples": [
                                "Is investing in the stocks better than bonds?",
                                "Should I invest in gold?"
                            ],
                            "Name": "Investment Advice",
                            "Type": "DENY"
                        }
                    ]
                },
                "WordPolicyConfig": {
                    "ManagedWordListsConfig": [
                        {
                            "Type": "PROFANITY"
                        }
                    ],
                    "WordsConfig": [
                        {
                            "Text": "BLOCKTHISWORD"
                        }
                    ]
                },
                "ContextualGroundingPolicyConfig": {
                    "FiltersConfig": [
                        {
                            "Threshold": "0.8",
                            "Type": "GROUNDING"
                        },
                        {
                            "Threshold": "0.8",
                            "Type": "RELEVANCE"
                        }
                    ]
                }
            }
        },
        "GuardrailVersion": {
            "Type": "AWS::Bedrock::GuardrailVersion",
            "Properties": {
                "Description": {
                    "Ref": "GuardrailVersionDescription"
                },
                "GuardrailIdentifier": {
                    "Fn::GetAtt": [
                        "Guardrail",
                        "GuardrailArn"
                    ]
                }
            }
        }
    }
}

{
  "AWSTemplateFormatVersion" : "2010-09-09",

  "Description" : "AWS CloudFormation Sample Template Route53_A: Sample template showing how to create an Amazon Route 53 A record that maps to the public IP address of an EC2 instance. It assumes that you already have a Hosted Zone registered with Amazon Route 53. **WARNING** This template creates an Amazon EC2 instance. You will be billed for the AWS resources used if you create a stack from this template.",

  "Parameters" : {
    "HostedZone" : {
      "Type" : "String",
      "Description" : "The DNS name of an existing Amazon Route 53 hosted zone"
    }
  },

  "Mappings" : {
    "RegionMap" : {
      "us-east-1"      : { "AMI" : "ami-7f418316" },
      "us-west-1"      : { "AMI" : "ami-951945d0" },
      "us-west-2"      : { "AMI" : "ami-16fd7026" },
      "eu-west-1"      : { "AMI" : "ami-24506250" },
      "sa-east-1"      : { "AMI" : "ami-3e3be423" },
      "ap-southeast-1" : { "AMI" : "ami-74dda626" },
      "ap-southeast-2" : { "AMI" : "ami-b3990e89" },
      "ap-northeast-1" : { "AMI" : "ami-dcfa4edd" }
    }
  },

  "Resources" : {
    "Ec2Instance" : {
      "Type" : "AWS::EC2::Instance",
      "Properties" : {
        "ImageId" : { "Fn::FindInMap" : [ "RegionMap", { "Ref" : "AWS::Region" }, "AMI" ]}
      }
    },
    "myDNSRecord" : {
      "Type" : "AWS::Route53::RecordSet",
      "Properties" : {
        "HostedZoneName" : { "Fn::Join" : [ "", [{"Ref" : "HostedZone"}, "." ]]},
        "Comment" : "DNS name for my instance.",
        "Name" : { "Fn::Join" : [ "", [{"Ref" : "Ec2Instance"}, ".", {"Ref" : "AWS::Region"}, ".", {"Ref" : "HostedZone"} ,"."]]},
        "Type" : "A",
        "TTL" : "900",
        "ResourceRecords" : [ { "Fn::GetAtt" : [ "Ec2Instance", "PublicIp" ] } ]
      }
    }
  },
  "Outputs" : {
    "DomainName" : {
      "Value" : { "Ref" : "myDNSRecord" }
    }
  }
}

{
  "AWSTemplateFormatVersion":"2010-09-09",
  "Description":"IAM Role enabling the MOC to administer their Prometheus server",
  "Metadata": {
    "Source":"https://github.com/mozilla/security/tree/master/operations/cloudformation-templates"
  },
  "Mappings":{
    "VariablesMap":{
      "MOC":{
        "ExternalAccountId":"093365119719",
        "TechnicalContact":"moc@mozilla.com"
      }
    }
  },
  "Resources":{
    "Role":{
      "Type":"AWS::IAM::Role",
      "Properties":{
        "RoleName": "MOCPrometheusAdmin",
        "AssumeRolePolicyDocument":{
          "Version":"2012-10-17",
          "Statement":[
            {
              "Effect":"Allow",
              "Action":"sts:AssumeRole",
              "Principal":{
                "AWS":{"Fn::Join":[":",["arn:aws:iam:",{"Fn::FindInMap":["VariablesMap","MOC","ExternalAccountId"]},"root"]]}
              }
            }
          ]
        },
        "Policies": [
          {
            "PolicyName" : "ControlMOCPrometheusInstance",
            "PolicyDocument" : {
              "Version": "2012-10-17",
              "Statement": [
                {
                  "Effect": "Allow",
                  "Action": [
                    "ec2:StopInstances",
                    "ec2:StartInstances",
                    "ec2:RebootInstances"
                  ],
                  "Resource": "*",
                  "Condition": {
                    "StringEquals" : {
                      "ec2:ResourceTag/TechnicalContact" : {"Fn::FindInMap":["VariablesMap","MOC","TechnicalContact"]}
                    }
                  }
                },
                {
                  "Effect": "Allow",
                  "Action": [
                    "ec2:DescribeInstances"
                  ],
                  "Resource": "*"
                }
              ]
            }
          }
        ]
      }
    }
  },
  "Outputs":{
    "AssumeRoleArn":{
      "Value":{"Fn::GetAtt" : ["Role", "Arn"] },
      "Description":"The ARN of the IAM Role"
    }
  }
}

{
    "AWSTemplateFormatVersion": "2010-09-09",
    "Description": "This template updates the specified route tables & security groups to allow communications via the VPC peering connection.",
    "Metadata": {
        "AWS::CloudFormation::Interface": {
            "ParameterGroups": [
                {
                    "Label": {
                        "default": "Network Configuration"
                    },
                    "Parameters": [
                        "RouteTableIds",
                        "NumberOfRouteTables",
                        "VPCPeeringConnectionId"
                    ]
                },
                {
                    "Label": {
                        "default": "Security Groups Configuration"
                    },
                    "Parameters": [
                        "SecurityGroupIds",
                        "NumberOfSecurityGroups"
                    ]
                },
                {
                    "Label": {
                        "default": "VPC Peering Configuration"
                    },
                    "Parameters": [
                        "PeerName",
                        "PeerVPCCIDR"
                    ]
                }
            ],
            "ParameterLabels": {
                "NumberOfRouteTables": {
                    "default": "Number of Route Tables"
                },
                "NumberOfSecurityGroups": {
                    "default": "Number of Security Groups"
                },
                "PeerName": {
                    "default": "Peer Name"
                },
                "PeerVPCCIDR": {
                    "default": "Peer VPC CIDR"
                },
                "RouteTableIds": {
                    "default": "Route Table IDs"
                },
                "SecurityGroupIds": {
                    "default": "Security Group IDs"
                },
                "VPCPeeringConnectionId": {
                    "default": "VPC Peering Connection ID"
                }
            }
        }
    },
    "Parameters": {
        "NumberOfRouteTables": {
            "AllowedValues": [
                1,
                2,
                3,
                4,
                5,
                6
            ],
            "Description": "Number of Route Table IDs to update. This must match your items in the comma-separated list of RouteTableIds parameter.",
            "Type": "String"
        },
        "NumberOfSecurityGroups": {
            "AllowedValues": [
                1,
                2,
                3,
                4,
                5,
                6
            ],
            "Description": "Number of Security Group IDs. This must match your selections in the list of SecurityGroupIds parameter.",
            "Type": "String"
        },
        "PeerName": {
            "Description": "Name of the VPC Peer",
            "MaxLength": 255,
            "Type": "String"
        },
        "PeerVPCCIDR": {
            "AllowedPattern": "^(([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])(\\/(1[6-9]|2[0-8]))$",
            "ConstraintDescription": "CIDR block parameter must be in the form x.x.x.x/16-28",
            "Description": "CIDR of the VPC Peer",
            "Type": "String"
        },
        "RouteTableIds": {
            "AllowedPattern": "^(rtb-[0-9a-f]{17})$|^((rtb-[0-9a-f]{17}(,|, ))*rtb-[0-9a-f]{17})$",
            "ConstraintDescription": "Must have a prefix of \"rtb-\". Followed by 17 characters (numbers, letters \"a-f\"). Additional route tables can be provided, separated by a \"comma\".",
            "Description": "Route Table IDs that will be updated to allow communications via the VPC peering connection. Note, the logical order is preserved.",
            "Type": "String"
        },
        "SecurityGroupIds": {
            "Description": "Security Group IDs that will be updated to allow communications via the VPC peering connection. Note, the logical order is preserved.",
            "Type": "List<AWS::EC2::SecurityGroup::Id>"
        },
        "VPCPeeringConnectionId": {
            "AllowedPattern": "^pcx-[0-9a-f]{17}$",
            "ConstraintDescription": "Must have a prefix of \"pcx-\". Followed by 17 characters (numbers, letters \"a-f\")",
            "Description": "ID of the VPC Peering Connection",
            "Type": "String"
        }
    },
    "Conditions": {
        "2RouteTableCondition": {
            "Fn::Or": [
                {
                    "Fn::Equals": [
                        {
                            "Ref": "NumberOfRouteTables"
                        },
                        2
                    ]
                },
                {
                    "Condition": "3RouteTableCondition"
                },
                {
                    "Condition": "4RouteTableCondition"
                },
                {
                    "Condition": "5RouteTableCondition"
                },
                {
                    "Condition": "6RouteTableCondition"
                }
            ]
        },
        "3RouteTableCondition": {
            "Fn::Or": [
                {
                    "Fn::Equals": [
                        {
                            "Ref": "NumberOfRouteTables"
                        },
                        3
                    ]
                },
                {
                    "Condition": "4RouteTableCondition"
                },
                {
                    "Condition": "5RouteTableCondition"
                },
                {
                    "Condition": "6RouteTableCondition"
                }
            ]
        },
        "4RouteTableCondition": {
            "Fn::Or": [
                {
                    "Fn::Equals": [
                        {
                            "Ref": "NumberOfRouteTables"
                        },
                        4
                    ]
                },
