{
  "AWSTemplateFormatVersion" : "2010-09-09",

  "Description" : "AWS CloudFormation Sample Template EC2InstanceSample: Create an Amazon EC2 instance running the Amazon Linux AMI. The AMI is chosen based on the region in which the stack is run. This example uses the default security group, so to SSH to the new instance using the KeyPair you enter, you will need to have port 22 open in your default security group. **WARNING** This template an Amazon EC2 instances. You will be billed for the AWS resources used if you create a stack from this template.",

  "Parameters" : {
    "KeyName" : {
      "Description" : "Name of an existing EC2 KeyPair to enable SSH access to the instance",
      "Type" : "String"
    }
  },

  "Mappings" : {
    "RegionMap" : {
      "us-east-1"      : { "AMI" : "ami-7f418316" },
      "us-west-1"      : { "AMI" : "ami-951945d0" },
      "us-west-2"      : { "AMI" : "ami-16fd7026" },
      "eu-west-1"      : { "AMI" : "ami-24506250" },
      "sa-east-1"      : { "AMI" : "ami-3e3be423" },
      "ap-southeast-1" : { "AMI" : "ami-74dda626" },
      "ap-southeast-2" : { "AMI" : "ami-b3990e89" },
      "ap-northeast-1" : { "AMI" : "ami-dcfa4edd" }
    }
  },

  "Resources" : {
    "Ec2Instance" : {
      "Type" : "AWS::EC2::Instance",
      "Properties" : {
        "KeyName" : { "Ref" : "KeyName" },
        "ImageId" : { "Fn::FindInMap" : [ "RegionMap", { "Ref" : "AWS::Region" }, "AMI" ]},
        "UserData" : { "Fn::Base64" : "80" }
      }
    }
  },

  "Outputs" : {
    "InstanceId" : {
      "Description" : "InstanceId of the newly created EC2 instance",
      "Value" : { "Ref" : "Ec2Instance" }
    },
    "AZ" : {
      "Description" : "Availability Zone of the newly created EC2 instance",
      "Value" : { "Fn::GetAtt" : [ "Ec2Instance", "AvailabilityZone" ] }
    },
    "PublicIP" : {
      "Description" : "Public IP address of the newly created EC2 instance",
      "Value" : { "Fn::GetAtt" : [ "Ec2Instance", "PublicIp" ] }
    },
    "PrivateIP" : {
      "Description" : "Private IP address of the newly created EC2 instance",
      "Value" : { "Fn::GetAtt" : [ "Ec2Instance", "PrivateIp" ] }
    },
    "PublicDNS" : {
      "Description" : "Public DNSName of the newly created EC2 instance",
      "Value" : { "Fn::GetAtt" : [ "Ec2Instance", "PublicDnsName" ] }
    },
    "PrivateDNS" : {
      "Description" : "Private DNSName of the newly created EC2 instance",
      "Value" : { "Fn::GetAtt" : [ "Ec2Instance", "PrivateDnsName" ] }
    }
  }
}

{
    "AWSTemplateFormatVersion": "2010-09-09",
        "Description": "Clients API IAM Policy",
        "Parameters": {
            "Namespace": {
                "Description": "The namespace which this table belongs to",
                "Type": "String",
                "Default": "development"
            }
        },
        "Resources": {
            "IamPolicy": {
                "Type": "AWS::IAM::ManagedPolicy",
                "Properties": {
                    "PolicyDocument" : {
                        "Version": "2012-10-17",
                        "Statement": [
                            {
                                "Effect": "Allow",
                                "Action": [
                                    "dynamodb:BatchGetItem",
                                    "dynamodb:PutItem",
                                    "dynamodb:DescribeTable",
                                    "dynamodb:DeleteItem",
                                    "dynamodb:GetItem",
                                    "dynamodb:Scan",
                                    "dynamodb:Query",
                                    "dynamodb:UpdateItem"
                                ],
                                "Resource": [
                                    { "Fn::Sub": "arn:aws:dynamodb:${AWS::Region}:${AWS::AccountId}:table/${Namespace}-clients" },
                                    { "Fn::Sub": "arn:aws:dynamodb:${AWS::Region}:${AWS::AccountId}:table/${AWS::AccountId}/index/*"}
                                ]
                            }
                        ]
                    },
                    "ManagedPolicyName" : { "Fn::Sub": "${Namespace}-ClientsApiPolicy" }
                }
            }
        },
        "Outputs": {
            "IamPolicyArn" : {
              "Value" : { "Ref" : "IamPolicy" }
            }
        }
    }

{
    "AWSTemplateFormatVersion": "2010-09-09",
    "Description": "This template enables VPC Flow Logs to CloudWatch.",
    "Metadata": {
        "AWS::CloudFormation::Interface": {
            "ParameterGroups": [
                {
                    "Label": {
                        "default": "Network Configuration"
                    },
                    "Parameters": [
                        "VPCID"
                    ]
                },
                {
                    "Label": {
                        "default": "VPC Flow Logs Configuration"
                    },
                    "Parameters": [
                        "VPCFlowLogsLogFormat",
                        "VPCFlowLogsMaxAggregationInterval",
                        "VPCFlowLogsTrafficType",
                        "VPCFlowLogsLogGroupRetention",
                        "VPCFlowLogsCloudWatchKMSKey"
                    ]
                }
            ],
            "ParameterLabels": {
                "VPCFlowLogsCloudWatchKMSKey": {
                    "default": "CloudWatch Logs KMS Key for VPC flow logs"
                },
                "VPCFlowLogsLogFormat": {
                    "default": "VPC Flow Logs - Log Format"
                },
                "VPCFlowLogsLogGroupRetention": {
                    "default": "CloudWatch log retention days for VPC flow logs"
                },
                "VPCFlowLogsMaxAggregationInterval": {
                    "default": "VPC Flow Logs - Max Aggregation Interval"
                },
                "VPCFlowLogsTrafficType": {
                    "default": "VPC Flow Logs - Traffic Type"
                },
                "VPCID": {
                    "default": "VPC ID"
                }
            }
        }
    },
    "Parameters": {
        "VPCFlowLogsCloudWatchKMSKey": {
            "AllowedPattern": "^$|^arn:(aws[a-zA-Z-]*)?:kms:[a-z0-9-]+:\\d{12}:key\\/[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$",
            "ConstraintDescription": "Key ARN example:  arn:aws:kms:us-east-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab",
            "Description": "(Optional) KMS Key ARN to use for encrypting the VPC flow logs data. If empty, encryption is enabled with CloudWatch Logs managing the server-side encryption keys.",
            "Type": "String"
        },
        "VPCFlowLogsLogFormat": {
            "AllowedPattern": "^(\\$\\{[a-z-]+\\})$|^((\\$\\{[a-z-]+\\} )*\\$\\{[a-z-]+\\})$",
            "Default": "${version} ${account-id} ${interface-id} ${srcaddr} ${dstaddr} ${srcport} ${dstport} ${protocol} ${packets} ${bytes} ${start} ${end} ${action} ${log-status}",
            "Description": "The fields to include in the flow log record, in the order in which they should appear. Specify the fields using the ${field-id} format, separated by spaces. Using the Default Format as the default value.",
            "Type": "String"
        },
        "VPCFlowLogsLogGroupRetention": {
            "AllowedValues": [
                1,
                3,
                5,
                7,
                14,
                30,
                60,
                90,
                120,
                150,
                180,
                365,
                400,
                545,
                731,
                1827,
                3653
            ],
            "Default": 14,
            "Description": "Number of days to retain the VPC Flow Logs in CloudWatch",
            "Type": "String"
        },
        "VPCFlowLogsMaxAggregationInterval": {
            "AllowedValues": [
                60,
                600
            ],
            "Default": 600,
            "Description": "The maximum interval of time during which a flow of packets is captured and aggregated into a flow log record. You can specify 60 seconds (1 minute) or 600 seconds (10 minutes).",
            "Type": "String"
        },
        "VPCFlowLogsTrafficType": {
            "AllowedValues": [
                "ACCEPT",
                "ALL",
                "REJECT"
            ],
            "Default": "REJECT",
            "Description": "The type of traffic to log. You can log traffic that the resource accepts or rejects, or all traffic.",
            "Type": "String"
        },
        "VPCID": {
            "Description": "ID of the VPC (e.g., vpc-0343606e)",
            "Type": "AWS::EC2::VPC::Id"
        }
    },
    "Conditions": {
        "VPCFlowLogsCloudWatchKMSKeyCondition": {
            "Fn::Not": [
                {
                    "Fn::Equals": [
                        {
                            "Ref": "VPCFlowLogsCloudWatchKMSKey"
                        },
                        ""
                    ]
                }
            ]
        }
    },
    "Resources": {
        "VPCFlowLogsRole": {
            "Type": "AWS::IAM::Role",
            "Properties": {
                "Description": "Rights to Publish VPC Flow Logs to CloudWatch Logs",
                "AssumeRolePolicyDocument": {
                    "Version": "2012-10-17",
                    "Statement": [
                        {
                            "Effect": "Allow",
                            "Action": "sts:AssumeRole",
                            "Principal": {
                                "Service": [
                                    "vpc-flow-logs.amazonaws.com"
                                ]
                            }
                        }
                    ]
                },
                "Path": "/",
                "Tags": [
                    {
                        "Key": "StackName",
                        "Value": {
                            "Ref": "AWS::StackName"
                        }
                    }
                ],
                "Policies": [
                    {
                        "PolicyName": "CloudWatchLogGroup",
                        "PolicyDocument": {
                            "Version": "2012-10-17",
                            "Statement": [
                                {
                                    "Sid": "CloudWatchLogs",
                                    "Effect": "Allow",
                                    "Action": [
                                        "logs:CreateLogStream",
                                        "logs:PutLogEvents",
                                        "logs:DescribeLogGroups",
                                        "logs:DescribeLogStreams"
                                    ],
                                    "Resource": {
                                        "Fn::GetAtt": [
                                            "VPCFlowLogsLogGroup",
                                            "Arn"
                                        ]
                                    }
                                }
                            ]
                        }
                    }
                ]
            }
        },
        "VPCFlowLogsLogGroup": {
            "Type": "AWS::Logs::LogGroup",
            "Properties": {
                "RetentionInDays": {
                    "Ref": "VPCFlowLogsLogGroupRetention"
                },
                "KmsKeyId": {
                    "Fn::If": [
                        "VPCFlowLogsCloudWatchKMSKeyCondition",
                        {
                            "Ref": "VPCFlowLogsCloudWatchKMSKey"
                        },
                        {
                            "Ref": "AWS::NoValue"
                        }
                    ]
                }
            }
        },
        "VPCFlowLogsToCloudWatch": {
            "Type": "AWS::EC2::FlowLog",
            "Properties": {
                "LogDestinationType": "cloud-watch-logs",
                "LogGroupName": {
                    "Ref": "VPCFlowLogsLogGroup"
                },
                "DeliverLogsPermissionArn": {
                    "Fn::GetAtt": [
                        "VPCFlowLogsRole",
                        "Arn"
                    ]
                },
                "LogFormat": {
                    "Ref": "VPCFlowLogsLogFormat"
                },
                "MaxAggregationInterval": {
                    "Ref": "VPCFlowLogsMaxAggregationInterval"
                },
                "ResourceId": {
                    "Ref": "VPCID"
                },
                "ResourceType": "VPC",
                "TrafficType": {
                    "Ref": "VPCFlowLogsTrafficType"
                },
                "Tags": [
                    {
                        "Key": "Name",
                        "Value": "VPC Flow Logs CloudWatch"
                    }
                ]
            }
        }
    },
    "Outputs": {
        "VPCFlowLogsLogGroup": {
            "Description": "CloudWatch Log Group where VPC Flow Log data will be published",
            "Value": {
                "Ref": "VPCFlowLogsLogGroup"
            }
        }
    }
}

{
  "AWSTemplateFormatVersion": "2010-09-09",

  "Description": "JENKINS IAM Settings 1.0.0 - Author Chris Moran",

  "Parameters": {
    "CfnBucketName": {
      "Type": "String"
    }
  },

  "Resources": {
    "InstanceRole":{
      "Type":"AWS::IAM::Role",
      "Properties":{
        "AssumeRolePolicyDocument":{
          "Statement":[
          {
            "Effect":"Allow",
            "Principal":{
              "Service":[
              "ec2.amazonaws.com"
              ]
            },
            "Action":[
              "sts:AssumeRole"
            ]
          }
          ]
        },
        "Path":"/"
      }
    },

    "RolePolicies":{
        "Type":"AWS::IAM::Policy",
        "Properties":{
          "PolicyName":"S3Download",
          "PolicyDocument":{
            "Statement":[
            {
              "Action":[
                "s3:ListBucket",
                "s3:GetBucketLocation",
                "s3:GetObject"
              ],
              "Effect":"Allow",
              "Resource": [
              {
                "Fn::Join": [ "", [
                "arn:aws:s3:::",
                "cfnstore"
                ] ]
            },

            {
              "Fn::Join": [ "", [
                "arn:aws:s3:::",
                "perrincfnstore/",
                { "Ref": "CfnBucketName"},
                "/*"
              ] ]
            }

          ]
            }
            ]
        },
        "Roles":[
          { "Ref":"InstanceRole" }
        ]
         }
      },

    "BucketProfile" : {
      "Type": "AWS::IAM::InstanceProfile",
        "Properties": {
          "Path": "/",
          "Roles": [
            { "Ref":  "InstanceRole"}
            ]
          }
      }
  },

  "Outputs": {
    "BucketProfile": {
      "Value": { "Ref": "BucketProfile"}
    },

    "InstanceRole": {
      "Value": { "Ref": "InstanceRole"}
    }
  }
}
